export type Version = 'Apex';

export interface Exercise {
  id: string;
  order: string; // e.g., '1A', '1B'
  name: string;
  sets: number;
  reps: string; // string to handle "6 / side"
  tempo: string;
  notes: string;
  weightGuide: string;
  videoUrl?: string;
  isRest?: boolean;
}

export interface WorkoutDay {
  id: string;
  title: string;
  focus: string;
  exercises: Exercise[];
}

export interface WorkoutPlan {
  Apex: Record<string, WorkoutDay>;
}

export interface ExerciseLog {
  exerciseId: string;
  setLogs: {
    weight: string;
    reps: string;
    effort: number; // 1-4 level theory
    completed: boolean;
  }[];
}

export interface SessionLog {
  id: string;
  date: string;
  version: Version;
  dayId: string; // e.g., 'monday'
  exercises: ExerciseLog[];
  feedback?: string;
  duration?: number; // minutes
}

export interface WeeklySchedule {
  [key: number]: string; // 0=Sunday, 1=Monday, etc. -> key to WorkoutDay
}

export interface SubstitutionMatrix {
  [dayId: string]: {
    [order: string]: Exercise[];
  };
}

import { SessionLog, Version, ExerciseLog } from '../types';

const LOGS_KEY = 'golf_tracker_logs';
const VERSION_KEY = 'golf_tracker_version';

export const getLogs = (): SessionLog[] => {
  const stored = localStorage.getItem(LOGS_KEY);
  return stored ? JSON.parse(stored) : [];
};

export const saveLog = (log: SessionLog) => {
  const logs = getLogs();
  logs.unshift(log); // Add to top
  localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
};

export const getPreferredVersion = (): Version => {
  return (localStorage.getItem(VERSION_KEY) as Version) || 'Apex';
};

export const setPreferredVersion = (v: Version) => {
  localStorage.setItem(VERSION_KEY, v);
};

export const getLastLogForExercise = (exerciseId: string): ExerciseLog | null => {
  const logs = getLogs();
  for (const session of logs) {
    const found = session.exercises.find(e => e.exerciseId === exerciseId);
    if (found) return found;
  }
  return null;
};

