import React, { useState, useMemo } from 'react';
import { Layout } from './components/Layout';
import { WorkoutSession } from './components/WorkoutSession';
import { History } from './components/History';
import { WORKOUTS, SCHEDULE } from './constants';
import { getPreferredVersion, setPreferredVersion } from './services/storageService';
import { Version, WorkoutDay } from './types';
import { Dumbbell, Play, Calendar, ChevronLeft, ChevronRight, List, Check, User, Info, ArrowLeft, Target } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('workout');
  const [version] = useState<Version>('Apex'); // Fixed version
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isSessionActive, setIsSessionActive] = useState(false);
  const [manualWorkout, setManualWorkout] = useState<WorkoutDay | null>(null);
  const [showLibrary, setShowLibrary] = useState(false);

  // Determine workout based on selectedDate
  const todayWorkout = useMemo(() => {
    if (manualWorkout) return manualWorkout;

    const dayIndex = selectedDate.getDay(); // 0-6
    const dayKey = SCHEDULE[dayIndex];
    if (dayKey && WORKOUTS[version][dayKey]) {
      return WORKOUTS[version][dayKey];
    }
    return null; // Rest day or undefined
  }, [version, selectedDate, manualWorkout]);

  const changeDate = (days: number) => {
    const newDate = new Date(selectedDate);
    newDate.setDate(selectedDate.getDate() + days);
    setSelectedDate(newDate);
    setManualWorkout(null); // Reset manual override when date changes
  };

  const handleDateInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.value) return;
    const [year, month, day] = e.target.value.split('-').map(Number);
    // Create date in local time
    setSelectedDate(new Date(year, month - 1, day));
    setManualWorkout(null);
  };

  const selectFromLibrary = (key: string) => {
    setManualWorkout(WORKOUTS[version][key]);
    setShowLibrary(false);
  };

  const renderContent = () => {
    if (activeTab === 'history') {
      return <History />;
    }

    if (activeTab === 'settings') {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-3 mb-2">
            <button 
              onClick={() => setActiveTab('workout')}
              className="p-3 -ml-3 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
            >
              <ArrowLeft size={28} />
            </button>
            <h2 className="text-2xl font-bold text-white leading-none">Settings</h2>
          </div>

          <div className="flex items-center gap-4 mb-6 p-5 bg-slate-800 rounded-2xl border border-slate-700">
            <div className="bg-blue-600/20 p-4 rounded-full">
              <User size={28} className="text-blue-500" />
            </div>
            <div>
              <p className="text-white font-bold text-lg">Training Profile</p>
              <p className="text-slate-400 text-sm mt-0.5">Current active protocol settings.</p>
            </div>
          </div>

          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Active Protocol</h3>

            <div 
              className="w-full relative text-left p-6 rounded-3xl border-2 bg-blue-900/10 border-blue-500/50 shadow-lg shadow-blue-900/10"
            >
              <div className="absolute top-5 right-5 bg-blue-500 text-white rounded-full p-1.5 shadow-sm">
                <Check size={18} strokeWidth={3} />
              </div>
              <div className="flex items-start gap-4">
                <div className="p-3.5 rounded-2xl bg-blue-600 text-white shadow-lg shadow-blue-600/30">
                  <Target size={28} />
                </div>
                <div>
                  <div className="font-bold text-xl text-white">Apex Protocol</div>
                  <p className="text-sm text-slate-400 mt-2 leading-relaxed pr-6">
                    Modified Limited Equipment Split. Focus on Golf Power, 10k Speed, and Hypertrophy.
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="bg-slate-800/50 p-5 rounded-2xl border border-dashed border-slate-700 text-slate-500 text-sm leading-relaxed mt-4 flex gap-3">
            <Info size={20} className="shrink-0 text-blue-500/50" />
            <p>This is the current prescribed workout plan tailored for your equipment availability.</p>
          </div>

          <button 
             onClick={() => setActiveTab('workout')}
             className="w-full mt-6 bg-slate-800 hover:bg-slate-700 text-white font-bold text-lg py-5 rounded-2xl border border-slate-700 flex items-center justify-center gap-2 transition-all"
          >
            Return to Workout
          </button>
        </div>
      );
    }

    if (isSessionActive && todayWorkout) {
      return (
        <WorkoutSession 
          day={todayWorkout} 
          version={version} 
          date={selectedDate} 
          onFinish={() => {
            setIsSessionActive(false);
            setManualWorkout(null);
          }}
          onBack={() => {
            setIsSessionActive(false);
          }}
        />
      );
    }

    const dateInputValue = selectedDate.toLocaleDateString('en-CA'); 

    if (showLibrary) {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-2 mb-4">
            <button onClick={() => setShowLibrary(false)} className="p-3 -ml-3 text-slate-400 hover:text-white active:scale-95 transition-transform">
              <ChevronLeft size={32} />
            </button>
            <h2 className="text-3xl font-bold text-white">Library</h2>
          </div>
          <p className="text-slate-400 text-base mb-4">Select a specific workout to perform today.</p>
          <div className="space-y-4">
            {Object.keys(WORKOUTS[version]).map(key => {
              const w = WORKOUTS[version][key];
              return (
                <button 
                  key={w.id}
                  onClick={() => selectFromLibrary(key)}
                  className="w-full text-left p-6 bg-slate-800 rounded-3xl border border-slate-700 active:border-blue-500 active:bg-slate-800/90 transition-all group shadow-sm"
                >
                  <div className="flex justify-between items-center mb-1">
                    <div className="text-xs font-bold text-blue-400 uppercase tracking-wider">
                      {key}
                    </div>
                  </div>
                  <div className="font-bold text-xl text-slate-100 group-hover:text-blue-400 transition-colors mb-1">{w.title}</div>
                  <div className="text-sm text-slate-400">{w.focus}</div>
                </button>
              );
            })}
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-8 py-2 animate-fade-in">
        <div className="text-center space-y-6">

          {/* Date Picker - Large Touch Targets */}
          <div className="flex items-center justify-between bg-slate-800 p-2 rounded-2xl border border-slate-700 w-full shadow-lg">
             <button onClick={() => changeDate(-1)} className="h-12 w-14 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-700 transition-colors active:scale-95">
               <ChevronLeft size={28} />
             </button>

             <div className="relative group flex-1 h-12 flex items-center justify-center">
                <div className="flex items-center gap-3 px-4 py-2 rounded-xl active:bg-slate-700/50 transition-colors">
                  <Calendar size={20} className="text-yellow-400" />
                  <span className="font-bold text-lg text-white">
                    {selectedDate.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}
                  </span>
                </div>
                <input 
                  type="date" 
                  value={dateInputValue}
                  onChange={handleDateInput}
                  className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                />
             </div>

             <button onClick={() => changeDate(1)} className="h-12 w-14 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-700 transition-colors active:scale-95">
               <ChevronRight size={28} />
             </button>
          </div>

          <div className="space-y-2 mt-4 px-2">
            <h2 className="text-slate-500 text-xs font-bold uppercase tracking-widest">
              {manualWorkout ? 'Manual Selection' : 'Today\'s Protocol'}
            </h2>
            {todayWorkout ? (
              <>
                <h1 className="text-3xl font-extrabold text-white leading-tight">{todayWorkout.title}</h1>
                <div className="inline-flex items-center px-4 py-1.5 rounded-full bg-blue-900/30 text-blue-300 text-sm font-bold border border-blue-500/20">
                  {todayWorkout.focus}
                </div>
              </>
            ) : (
              <h1 className="text-3xl font-extrabold text-white">Rest & Recovery</h1>
            )}
          </div>
        </div>

        {todayWorkout ? (
          <div className="bg-gradient-to-b from-blue-600 to-blue-800 p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group">
            <div className="absolute -top-24 -right-24 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
            <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-black/20 rounded-full blur-3xl"></div>

            <div className="relative z-10 flex flex-col items-center gap-8">
              <div className="bg-white/10 p-5 rounded-full backdrop-blur-sm border border-white/20 shadow-xl">
                <Dumbbell className="w-10 h-10 text-white" />
              </div>

              <div className="text-center space-y-1">
                 <p className="text-blue-100 font-medium">Est. Duration</p>
                 <p className="text-white font-bold text-2xl">45-60 Min</p>
              </div>

              <div className="flex flex-col w-full gap-4">
                <button 
                  onClick={() => setIsSessionActive(true)}
                  className="w-full bg-white text-blue-900 font-extrabold text-xl py-5 rounded-2xl flex items-center justify-center gap-3 transition-transform active:scale-[0.98] shadow-lg"
                >
                  <Play fill="currentColor" size={24} />
                  Start Workout
                </button>

                <button 
                  onClick={() => setShowLibrary(true)}
                  className="w-full bg-blue-900/40 hover:bg-blue-900/60 text-blue-100 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 border border-white/10 transition-colors backdrop-blur-md"
                >
                  <List size={20} />
                  Change Workout
                </button>
              </div>
            </div>
          </div>
        ) : (
           <div className="bg-slate-800 p-8 rounded-[2rem] border border-slate-700 text-center shadow-xl">
             <div className="mb-8 flex justify-center opacity-70">
                <div className="bg-slate-700/50 p-6 rounded-full border border-slate-600">
                  <Calendar size={40} className="text-slate-300" />
                </div>
             </div>
             <h3 className="text-xl font-bold text-white mb-2">Rest Day</h3>
             <p className="text-slate-400 mb-8 leading-relaxed">Active recovery is recommended. Go for a walk or do some light stretching.</p>
             <button 
               onClick={() => setShowLibrary(true)}
               className="w-full bg-slate-700 hover:bg-slate-600 text-white font-bold py-4 rounded-2xl border border-slate-600 transition-colors flex items-center justify-center gap-2"
             >
               <List size={20} />
               Browse Library
             </button>
           </div>
        )}

        {/* Quick Stats Teaser */}
        <div className="grid grid-cols-2 gap-4">
           <div className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50">
              <div className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Streak</div>
              <div className="text-2xl font-bold text-white flex items-center gap-2">
                 3 <span className="text-sm font-medium text-slate-400">Days</span>
              </div>
           </div>
           <div className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50">
              <div className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Last Session</div>
              <div className="text-lg font-bold text-white truncate">
                Full Body Force
              </div>
           </div>
        </div>
      </div>
    );
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

