import React, { useState, useMemo, useEffect } from 'react';
import { Layout } from './components/Layout';
import { WorkoutSession } from './components/WorkoutSession';
import { History } from './components/History';
import { WORKOUTS, SCHEDULE } from './constants';
import { getPreferredVersion, setPreferredVersion, getApiKey, setApiKey } from './services/storageService';
import { generateWorkout } from './services/geminiService';
import { Version, WorkoutDay } from './types';
import { Dumbbell, Play, Calendar, ChevronLeft, ChevronRight, List, Check, User, Info, ArrowLeft, Target, WifiOff, Key, ExternalLink, Trash2, ShieldCheck, Sparkles, Loader2, Clock, Activity, Hash } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('workout');
  const [version] = useState<Version>('Apex'); // Fixed version
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isSessionActive, setIsSessionActive] = useState(false);
  const [manualWorkout, setManualWorkout] = useState<WorkoutDay | null>(null);
  const [showLibrary, setShowLibrary] = useState(false);
  const [showAIBuilder, setShowAIBuilder] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  // API Key State
  const [userApiKey, setUserApiKey] = useState(getApiKey());
  const [tempApiKey, setTempApiKey] = useState('');

  // AI Builder State
  const [aiParams, setAiParams] = useState({
    exerciseCount: '5',
    duration: '45 mins',
    equipment: 'Full Gym'
  });
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Determine workout based on selectedDate
  const todayWorkout = useMemo(() => {
    if (manualWorkout) return manualWorkout;

    const dayIndex = selectedDate.getDay(); // 0-6
    const dayKey = SCHEDULE[dayIndex];
    if (dayKey && WORKOUTS[version][dayKey]) {
      return WORKOUTS[version][dayKey];
    }
    return null; // Rest day or undefined
  }, [version, selectedDate, manualWorkout]);

  const changeDate = (days: number) => {
    const newDate = new Date(selectedDate);
    newDate.setDate(selectedDate.getDate() + days);
    setSelectedDate(newDate);
    setManualWorkout(null); // Reset manual override when date changes
  };

  const handleDateInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.value) return;
    const [year, month, day] = e.target.value.split('-').map(Number);
    // Create date in local time
    setSelectedDate(new Date(year, month - 1, day));
    setManualWorkout(null);
  };

  const handleSaveKey = () => {
    if (!tempApiKey.trim()) return;
    setUserApiKey(tempApiKey.trim());
    setApiKey(tempApiKey.trim());
    setTempApiKey(''); // Clear temp input for security
  };

  const handleRemoveKey = () => {
    setUserApiKey('');
    setApiKey('');
    setTempApiKey('');
  };

  const selectFromLibrary = (key: string) => {
    setManualWorkout(WORKOUTS[version][key]);
    setShowLibrary(false);
  };

  const handleGenerateWorkout = async () => {
    if (!userApiKey) {
      alert("Please add your API Key in Settings first.");
      setActiveTab('settings');
      setShowAIBuilder(false);
      return;
    }

    setIsGenerating(true);
    try {
      const generated = await generateWorkout(aiParams.exerciseCount, aiParams.duration, aiParams.equipment);
      if (generated) {
        setManualWorkout(generated);
        setShowAIBuilder(false);
      }
    } catch (error) {
      alert("Failed to generate workout. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    if (activeTab === 'history') {
      return <History />;
    }

    if (activeTab === 'settings') {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-3 mb-2">
            <button 
              onClick={() => setActiveTab('workout')}
              className="p-3 -ml-3 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
            >
              <ArrowLeft size={28} />
            </button>
            <h2 className="text-2xl font-bold text-white leading-none">Settings</h2>
          </div>

          <div className="flex items-center gap-4 mb-6 p-5 bg-slate-800 rounded-2xl border border-slate-700">
            <div className="bg-blue-600/20 p-4 rounded-full">
              <User size={28} className="text-blue-500" />
            </div>
            <div>
              <p className="text-white font-bold text-lg">Training Profile</p>
              <p className="text-slate-400 text-sm mt-0.5">Current active protocol settings.</p>
            </div>
          </div>

          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Active Protocol</h3>

            <div 
              className="w-full relative text-left p-6 rounded-3xl border-2 bg-blue-900/10 border-blue-500/50 shadow-lg shadow-blue-900/10"
            >
              <div className="absolute top-5 right-5 bg-blue-500 text-white rounded-full p-1.5 shadow-sm">
                <Check size={18} strokeWidth={3} />
              </div>
              <div className="flex items-start gap-4">
                <div className="p-3.5 rounded-2xl bg-blue-600 text-white shadow-lg shadow-blue-600/30">
                  <Target size={28} />
                </div>
                <div>
                  <div className="font-bold text-xl text-white">Apex Protocol</div>
                  <p className="text-sm text-slate-400 mt-2 leading-relaxed pr-6">
                    Modified Limited Equipment Split. Focus on Golf Power, 10k Speed, and Hypertrophy.
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-4 mt-6">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">AI Coaching</h3>

            {userApiKey ? (
              // SAVED STATE
              <div className="bg-slate-800 p-6 rounded-2xl border border-green-500/30 shadow-sm flex flex-col items-center text-center gap-4">
                <div className="bg-green-500/10 p-4 rounded-full ring-1 ring-green-500/20">
                   <ShieldCheck size={32} className="text-green-500" />
                </div>
                <div>
                   <h3 className="text-white font-bold text-lg">API Key Active</h3>
                   <p className="text-slate-400 text-sm mt-1 max-w-[250px] mx-auto">Your Gemini AI key is saved locally on this device.</p>
                </div>
                <button
                  onClick={handleRemoveKey}
                  className="flex items-center gap-2 px-5 py-3 bg-red-500/10 text-red-400 rounded-xl border border-red-500/20 font-bold text-sm hover:bg-red-500/20 transition-colors w-full justify-center mt-2"
                >
                  <Trash2 size={16} /> Delete Key
                </button>
              </div>
            ) : (
              // INPUT STATE
              <div className="bg-slate-800 p-5 rounded-2xl border border-slate-700 space-y-4 shadow-sm">
                  <div>
                      <div className="flex justify-between items-center mb-3">
                        <label className="text-white font-bold flex items-center gap-2">
                          <Key size={16} className="text-yellow-400" />
                          Gemini API Key
                        </label>
                        <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer" className="text-[10px] text-blue-400 font-bold bg-blue-500/10 px-2 py-1 rounded-md flex items-center gap-1 hover:bg-blue-500/20 transition">
                           GET KEY <ExternalLink size={10} />
                        </a>
                      </div>
                      <input 
                          type="password" 
                          value={tempApiKey}
                          onChange={(e) => setTempApiKey(e.target.value)}
                          placeholder="Paste your API Key here"
                          className="w-full bg-slate-900 border border-slate-600 rounded-xl p-4 text-white focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all placeholder:text-slate-600 font-mono text-sm"
                      />
                      <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                          Your key is required for AI feedback. It is stored locally and never sent to our servers.
                      </p>

                      <button
                        onClick={handleSaveKey}
                        disabled={!tempApiKey.trim()}
                        className="w-full mt-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-blue-900/20"
                      >
                        Save Key
                      </button>
                  </div>
              </div>
            )}
          </div>

          <button 
             onClick={() => setActiveTab('workout')}
             className="w-full mt-6 bg-slate-800 hover:bg-slate-700 text-white font-bold text-lg py-5 rounded-2xl border border-slate-700 flex items-center justify-center gap-2 transition-all"
          >
            Return to Workout
          </button>
        </div>
      );
    }

    if (isSessionActive && todayWorkout) {
      return (
        <WorkoutSession 
          day={todayWorkout} 
          version={version} 
          date={selectedDate} 
          onFinish={() => {
            setIsSessionActive(false);
            setManualWorkout(null);
          }}
          onBack={() => {
            setIsSessionActive(false);
          }}
        />
      );
    }

    const dateInputValue = selectedDate.toLocaleDateString('en-CA'); 
    const isAIWorkout = todayWorkout && todayWorkout.id.startsWith('ai_');

    if (showAIBuilder) {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-2 mb-4">
            <button onClick={() => setShowAIBuilder(false)} className="p-3 -ml-3 text-slate-400 hover:text-white active:scale-95 transition-transform">
              <ChevronLeft size={32} />
            </button>
            <h2 className="text-3xl font-bold text-white bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-blue-400">AI Coach</h2>
          </div>

          <div className="bg-slate-800/80 p-6 rounded-3xl border border-slate-700 space-y-6 shadow-xl">
             <div className="space-y-2">
               <label className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center gap-2">
                 <Hash size={14} /> Number of Exercises
               </label>
               <input 
                 type="text"
                 value={aiParams.exerciseCount}
                 onChange={(e) => setAiParams({...aiParams, exerciseCount: e.target.value})}
                 placeholder="e.g. 5, or 4-6"
                 className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white font-semibold focus:border-blue-500 outline-none placeholder:text-slate-600"
               />
               <p className="text-xs text-slate-500">How many movements do you want to do?</p>
             </div>

             <div className="space-y-2">
               <label className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center gap-2">
                 <Clock size={14} /> Available Time
               </label>
               <input 
                 type="text"
                 value={aiParams.duration}
                 onChange={(e) => setAiParams({...aiParams, duration: e.target.value})}
                 placeholder="e.g. 45 mins, 1 hour..."
                 className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white font-semibold focus:border-blue-500 outline-none placeholder:text-slate-600"
               />
             </div>

             <div className="space-y-2">
               <label className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center gap-2">
                 <Dumbbell size={14} /> Tools & Equipment
               </label>
               <input 
                 type="text"
                 value={aiParams.equipment}
                 onChange={(e) => setAiParams({...aiParams, equipment: e.target.value})}
                 placeholder="e.g. Dumbbells, Bench, Bands..."
                 className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white font-semibold focus:border-blue-500 outline-none placeholder:text-slate-600"
               />
               <p className="text-xs text-slate-500">Be specific (e.g. "Hotel Gym", "Bodyweight Only").</p>
             </div>
          </div>

          <button 
            onClick={handleGenerateWorkout}
            disabled={isGenerating}
            className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 text-white font-bold text-xl py-5 rounded-2xl shadow-xl shadow-purple-900/20 flex items-center justify-center gap-3 transition-all active:scale-[0.98]"
          >
            {isGenerating ? (
              <>
                <Loader2 className="animate-spin" /> Generating Plan...
              </>
            ) : (
              <>
                <Sparkles fill="currentColor" /> Generate Workout
              </>
            )}
          </button>
        </div>
      );
    }

    if (showLibrary) {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-2 mb-4">
            <button onClick={() => setShowLibrary(false)} className="p-3 -ml-3 text-slate-400 hover:text-white active:scale-95 transition-transform">
              <ChevronLeft size={32} />
            </button>
            <h2 className="text-3xl font-bold text-white">Library</h2>
          </div>
          <p className="text-slate-400 text-base mb-4">Select a specific workout to perform today.</p>
          <div className="space-y-4">
            {Object.keys(WORKOUTS[version]).map(key => {
              const w = WORKOUTS[version][key];
              return (
                <button 
                  key={w.id}
                  onClick={() => selectFromLibrary(key)}
                  className="w-full text-left p-6 bg-slate-800 rounded-3xl border border-slate-700 active:border-blue-500 active:bg-slate-800/90 transition-all group shadow-sm"
                >
                  <div className="flex justify-between items-center mb-1">
                    <div className="text-xs font-bold text-blue-400 uppercase tracking-wider">
                      {key}
                    </div>
                  </div>
                  <div className="font-bold text-xl text-slate-100 group-hover:text-blue-400 transition-colors mb-1">{w.title}</div>
                  <div className="text-sm text-slate-400">{w.focus}</div>
                </button>
              );
            })}
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-8 py-2 animate-fade-in">
        <div className="text-center space-y-6">

          {/* Date Picker - Large Touch Targets */}
          <div className="flex items-center justify-between bg-slate-800 p-2 rounded-2xl border border-slate-700 w-full shadow-lg">
             <button onClick={() => changeDate(-1)} className="h-12 w-14 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-700 transition-colors active:scale-95">
