                  value={dateInputValue}
                  onChange={handleDateInput}
                  className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                />
             </div>

             <button onClick={() => changeDate(1)} className="h-12 w-14 flex items-center justify-center rounded-xl text-slate-400 hover:text-white hover:bg-slate-700 transition-colors active:scale-95">
