          <div className="space-y-2 mt-4 px-2">
            <h2 className="text-slate-500 text-xs font-bold uppercase tracking-widest">
              {manualWorkout ? (manualWorkout.id.startsWith('ai_') ? 'AI Custom Plan' : 'Manual Selection') : 'Today\'s Protocol'}
            </h2>
            {todayWorkout ? (
              <>
                <h1 className="text-3xl font-extrabold text-white leading-tight">{todayWorkout.title}</h1>
                <div className={`inline-flex items-center px-4 py-1.5 rounded-full text-sm font-bold border ${isAIWorkout ? 'bg-purple-900/40 text-purple-300 border-purple-500/30' : 'bg-blue-900/30 text-blue-300 border-blue-500/20'}`}>
