import React, { useState, useMemo, useEffect } from 'react';
import { Layout } from './components/Layout';
import { WorkoutSession } from './components/WorkoutSession';
import { History } from './components/History';
import { WORKOUTS, SCHEDULE } from './constants';
import { getPreferredVersion, setPreferredVersion, getApiKey, setApiKey } from './services/storageService';
import { generateWorkout } from './services/geminiService';
import { Version, WorkoutDay } from './types';
import { Dumbbell, Play, Calendar, ChevronLeft, ChevronRight, List, Check, User, Info, ArrowLeft, Target, WifiOff, Key, ExternalLink, Trash2, ShieldCheck, Sparkles, Loader2, Clock, Activity, Hash } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('workout');
  const [version] = useState<Version>('Apex'); // Fixed version
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isSessionActive, setIsSessionActive] = useState(false);
  const [manualWorkout, setManualWorkout] = useState<WorkoutDay | null>(null);
  const [showLibrary, setShowLibrary] = useState(false);
  const [showAIBuilder, setShowAIBuilder] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  // API Key State
  const [userApiKey, setUserApiKey] = useState(getApiKey());
  const [tempApiKey, setTempApiKey] = useState('');

  // AI Builder State
  const [aiParams, setAiParams] = useState({
    exerciseCount: '5',
    duration: '45 mins',
    equipment: 'Full Gym'
  });
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Determine workout based on selectedDate
  const todayWorkout = useMemo(() => {
    if (manualWorkout) return manualWorkout;

    const dayIndex = selectedDate.getDay(); // 0-6
    const dayKey = SCHEDULE[dayIndex];
    if (dayKey && WORKOUTS[version][dayKey]) {
      return WORKOUTS[version][dayKey];
    }
    return null; // Rest day or undefined
  }, [version, selectedDate, manualWorkout]);

  const changeDate = (days: number) => {
    const newDate = new Date(selectedDate);
    newDate.setDate(selectedDate.getDate() + days);
    setSelectedDate(newDate);
    setManualWorkout(null); // Reset manual override when date changes
  };

  const handleDateInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.value) return;
    const [year, month, day] = e.target.value.split('-').map(Number);
    // Create date in local time
    setSelectedDate(new Date(year, month - 1, day));
    setManualWorkout(null);
  };

  const handleSaveKey = () => {
    if (!tempApiKey.trim()) return;
    setUserApiKey(tempApiKey.trim());
    setApiKey(tempApiKey.trim());
    setTempApiKey(''); // Clear temp input for security
  };

  const handleRemoveKey = () => {
    setUserApiKey('');
    setApiKey('');
    setTempApiKey('');
  };

  const selectFromLibrary = (key: string) => {
    setManualWorkout(WORKOUTS[version][key]);
    setShowLibrary(false);
  };

  const handleGenerateWorkout = async () => {
    if (!userApiKey) {
      alert("Please add your API Key in Settings first.");
      setActiveTab('settings');
      setShowAIBuilder(false);
      return;
    }

    setIsGenerating(true);
    try {
      const generated = await generateWorkout(aiParams.exerciseCount, aiParams.duration, aiParams.equipment);
      if (generated) {
        setManualWorkout(generated);
        setShowAIBuilder(false);
      }
    } catch (error) {
      alert("Failed to generate workout. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    if (activeTab === 'history') {
      return <History />;
    }

    if (activeTab === 'settings') {
      return (
        <div className="space-y-6 animate-fade-in">
          <div className="flex items-center gap-3 mb-2">
            <button 
              onClick={() => setActiveTab('workout')}
              className="p-3 -ml-3 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
            >
              <ArrowLeft size={28} />
            </button>
            <h2 className="text-2xl font-bold text-white leading-none">Settings</h2>
          </div>

          <div className="flex items-center gap-4 mb-6 p-5 bg-slate-800 rounded-2xl border border-slate-700">
            <div className="bg-blue-600/20 p-4 rounded-full">
              <User size={28} className="text-blue-500" />
            </div>
            <div>
              <p className="text-white font-bold text-lg">Training Profile</p>
              <p className="text-slate-400 text-sm mt-0.5">Current active protocol settings.</p>
            </div>
          </div>

          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest ml-1">Active Protocol</h3>

            <div 
              className="w-full relative text-left p-6 rounded-3xl border-2 bg-blue-900/10 border-blue-500/50 shadow-lg shadow-blue-900/10"
            >
              <div className="absolute top-5 right-5 bg-blue-500 text-white rounded-full p-1.5 shadow-sm">
                <Check size={18} strokeWidth={3} />
              </div>
              <div className="flex items-start gap-4">
                <div className="p-3.5 rounded-2xl bg-blue-600 text-white shadow-lg shadow-blue-600/30">
                  <Target size={28} />
