                   <p className="text-slate-400 text-sm mt-1 max-w-[250px] mx-auto">Your Gemini AI key is saved locally on this device.</p>
                </div>
                <button
                  onClick={handleRemoveKey}
                  className="flex items-center gap-2 px-5 py-3 bg-red-500/10 text-red-400 rounded-xl border border-red-500/20 font-bold text-sm hover:bg-red-500/20 transition-colors w-full justify-center mt-2"
                >
                  <Trash2 size={16} /> Delete Key
                </button>
              </div>
            ) : (
              // INPUT STATE
              <div className="bg-slate-800 p-5 rounded-2xl border border-slate-700 space-y-4 shadow-sm">
                  <div>
                      <div className="flex justify-between items-center mb-3">
                        <label className="text-white font-bold flex items-center gap-2">
                          <Key size={16} className="text-yellow-400" />
                          Gemini API Key
                        </label>
                        <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer" className="text-[10px] text-blue-400 font-bold bg-blue-500/10 px-2 py-1 rounded-md flex items-center gap-1 hover:bg-blue-500/20 transition">
                           GET KEY <ExternalLink size={10} />
                        </a>
                      </div>
                      <input 
                          type="password" 
                          value={tempApiKey}
                          onChange={(e) => setTempApiKey(e.target.value)}
                          placeholder="Paste your API Key here"
                          className="w-full bg-slate-900 border border-slate-600 rounded-xl p-4 text-white focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all placeholder:text-slate-600 font-mono text-sm"
                      />
                      <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                          Your key is required for AI feedback. It is stored locally and never sent to our servers.
                      </p>

                      <button
                        onClick={handleSaveKey}
                        disabled={!tempApiKey.trim()}
                        className="w-full mt-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-blue-900/20"
                      >
                        Save Key
                      </button>
                  </div>
              </div>
            )}
          </div>

          <button 
             onClick={() => setActiveTab('workout')}
             className="w-full mt-6 bg-slate-800 hover:bg-slate-700 text-white font-bold text-lg py-5 rounded-2xl border border-slate-700 flex items-center justify-center gap-2 transition-all"
          >
            Return to Workout
          </button>
        </div>
      );
