                 value={aiParams.equipment}
                 onChange={(e) => setAiParams({...aiParams, equipment: e.target.value})}
                 placeholder="e.g. Dumbbells, Bench, Bands..."
                 className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white font-semibold focus:border-blue-500 outline-none placeholder:text-slate-600"
