               <p className="text-xs text-slate-500">Be specific (e.g. "Hotel Gym", "Bodyweight Only").</p>
             </div>
          </div>

          <button 
            onClick={handleGenerateWorkout}
            disabled={isGenerating}
            className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 text-white font-bold text-xl py-5 rounded-2xl shadow-xl shadow-purple-900/20 flex items-center justify-center gap-3 transition-all active:scale-[0.98]"
          >
            {isGenerating ? (
              <>
                <Loader2 className="animate-spin" /> Generating Plan...
