              </>
            ) : (
              <h1 className="text-3xl font-extrabold text-white">Rest & Recovery</h1>
            )}
          </div>
        </div>

        {todayWorkout ? (
          <div className={`p-8 rounded-[2rem] shadow-2xl relative overflow-hidden group ${
            isAIWorkout 
              ? 'bg-gradient-to-br from-violet-600 via-purple-700 to-indigo-900 shadow-purple-900/40' 
              : 'bg-gradient-to-b from-blue-600 to-blue-800'
          }`}>
            <div className={`absolute -top-24 -right-24 w-64 h-64 rounded-full blur-3xl ${isAIWorkout ? 'bg-fuchsia-400/20' : 'bg-white/10'}`}></div>
            <div className={`absolute -bottom-24 -left-24 w-64 h-64 rounded-full blur-3xl ${isAIWorkout ? 'bg-indigo-400/20' : 'bg-black/20'}`}></div>

            <div className="relative z-10 flex flex-col items-center gap-8">
              <div className="bg-white/10 p-5 rounded-full backdrop-blur-sm border border-white/20 shadow-xl">
                {isAIWorkout ? <Sparkles className="w-10 h-10 text-white" /> : <Dumbbell className="w-10 h-10 text-white" />}
              </div>

              <div className="text-center space-y-1">
                 <p className="text-blue-100 font-medium">Est. Duration</p>
                 <p className="text-white font-bold text-2xl">45-60 Min</p>
              </div>

              <div className="flex flex-col w-full gap-4">
                <button 
                  onClick={() => setIsSessionActive(true)}
                  className={`w-full bg-white font-extrabold text-xl py-5 rounded-2xl flex items-center justify-center gap-3 transition-transform active:scale-[0.98] shadow-lg ${
                    isAIWorkout ? 'text-purple-900' : 'text-blue-900'
                  }`}
                >
                  <Play fill="currentColor" size={24} />
                  Start Workout
                </button>

                <button 
                  onClick={() => setShowLibrary(true)}
                  className={`w-full font-bold py-4 rounded-2xl flex items-center justify-center gap-2 border border-white/10 transition-colors backdrop-blur-md ${
                     isAIWorkout ? 'bg-purple-900/40 hover:bg-purple-900/60 text-purple-100' : 'bg-blue-900/40 hover:bg-blue-900/60 text-blue-100'
                  }`}
                >
                  <List size={20} />
                  Change Workout
                </button>
              </div>
            </div>
          </div>
        ) : (
           <div className="bg-slate-800 p-8 rounded-[2rem] border border-slate-700 text-center shadow-xl">
             <div className="mb-8 flex justify-center opacity-70">
                <div className="bg-slate-700/50 p-6 rounded-full border border-slate-600">
                  <Calendar size={40} className="text-slate-300" />
                </div>
             </div>
             <h3 className="text-xl font-bold text-white mb-2">Rest Day</h3>
             <p className="text-slate-400 mb-8 leading-relaxed">Active recovery is recommended. Go for a walk or do some light stretching.</p>
             <button 
               onClick={() => setShowLibrary(true)}
               className="w-full bg-slate-700 hover:bg-slate-600 text-white font-bold py-4 rounded-2xl border border-slate-600 transition-colors flex items-center justify-center gap-2"
             >
               <List size={20} />
               Browse Library
             </button>
           </div>
        )}

        {/* AI Builder Entry Point - Always Visible */}
        <div className="mt-4">
            <button 
                onClick={() => setShowAIBuilder(true)}
                className="w-full bg-gradient-to-r from-purple-900/50 to-blue-900/50 border border-purple-500/30 p-6 rounded-3xl flex items-center justify-between group hover:border-purple-500/50 transition-all"
            >
                <div className="flex items-center gap-4">
                    <div className="bg-purple-500 p-3 rounded-xl text-white shadow-lg shadow-purple-900/40">
                    <Sparkles size={24} fill="currentColor" />
                    </div>
                    <div className="text-left">
                    <div className="text-white font-bold text-lg">AI Coach</div>
                    <div className="text-purple-300 text-sm">Build a custom plan</div>
                    </div>
                </div>
                <ChevronRight className="text-purple-400" />
            </button>
        </div>

        {/* Quick Stats Teaser */}
        <div className="grid grid-cols-2 gap-4">
           <div className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50">
              <div className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Streak</div>
              <div className="text-2xl font-bold text-white flex items-center gap-2">
                 3 <span className="text-sm font-medium text-slate-400">Days</span>
              </div>
           </div>
           <div className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50">
              <div className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Last Session</div>
              <div className="text-lg font-bold text-white truncate">
                Full Body Force
              </div>
           </div>
        </div>
      </div>
    );
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab}>
      {isOffline && (
        <div className="bg-amber-600/90 backdrop-blur-sm text-white text-center py-2 px-4 text-xs font-bold flex items-center justify-center gap-2 sticky top-0 z-[60]">
          <WifiOff size={14} />
          Offline Mode Active - Data Saved Locally
        </div>
      )}
      {renderContent()}
    </Layout>
  );
};

