import { SessionLog, Version, ExerciseLog, Exercise } from '../types';

const LOGS_KEY = 'golf_tracker_logs';
const VERSION_KEY = 'golf_tracker_version';
const API_KEY_KEY = 'golf_tracker_api_key';
const DRAFT_KEY_PREFIX = 'golf_tracker_draft_';
const PREFS_KEY_PREFIX = 'golf_tracker_prefs_';

export const getLogs = (): SessionLog[] => {
  const stored = localStorage.getItem(LOGS_KEY);
  return stored ? JSON.parse(stored) : [];
};

export const saveLog = (log: SessionLog) => {
  const logs = getLogs();
  logs.unshift(log); // Add to top
  localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
  clearDraft(log.dayId); // Clear draft once successfully saved
};

export const getPreferredVersion = (): Version => {
  return (localStorage.getItem(VERSION_KEY) as Version) || 'Apex';
};

export const setPreferredVersion = (v: Version) => {
  localStorage.setItem(VERSION_KEY, v);
};

export const getLastLogForExercise = (exerciseId: string): ExerciseLog | null => {
  const logs = getLogs();
  for (const session of logs) {
    const found = session.exercises.find(e => e.exerciseId === exerciseId);
    if (found) return found;
  }
  return null;
};

// --- API Key ---
export const getApiKey = (): string => {
  return localStorage.getItem(API_KEY_KEY) || '';
};

export const setApiKey = (key: string) => {
  localStorage.setItem(API_KEY_KEY, key);
};

// --- Workout Drafts (Auto-Save) ---
export interface WorkoutDraft {
  dayId: string;
  exercises: Exercise[];
  logs: ExerciseLog[];
  date: string;
}

export const saveDraft = (draft: WorkoutDraft) => {
  localStorage.setItem(`${DRAFT_KEY_PREFIX}${draft.dayId}`, JSON.stringify(draft));
};

export const getDraft = (dayId: string): WorkoutDraft | null => {
  const stored = localStorage.getItem(`${DRAFT_KEY_PREFIX}${dayId}`);
  return stored ? JSON.parse(stored) : null;
};

export const clearDraft = (dayId: string) => {
  localStorage.removeItem(`${DRAFT_KEY_PREFIX}${dayId}`);
};

// --- Exercise Preferences (Substitutions) ---
export const saveExercisePreference = (dayId: string, order: string, exerciseId: string) => {
  const prefs = getExercisePreferences(dayId);
  prefs[order] = exerciseId;
  localStorage.setItem(`${PREFS_KEY_PREFIX}${dayId}`, JSON.stringify(prefs));
};

export const getExercisePreferences = (dayId: string): Record<string, string> => {
  const stored = localStorage.getItem(`${PREFS_KEY_PREFIX}${dayId}`);
  return stored ? JSON.parse(stored) : {};
};

import React, { useState, useEffect, useRef } from 'react';
import { WorkoutDay, ExerciseLog, Version, Exercise } from '../types';
import { WORKOUTS, SUBSTITUTION_MATRIX } from '../constants';
import { CheckCircle2, Circle, Clock, Info, Save, ChevronLeft, RefreshCw, X, Check, Plus, Minus, Gauge, ChevronDown, Trash2, Sparkles } from 'lucide-react';
import { saveLog, getLastLogForExercise, saveDraft, getDraft, saveExercisePreference, getExercisePreferences } from '../services/storageService';
import { analyzeSession } from '../services/geminiService';

interface WorkoutSessionProps {
  day: WorkoutDay;
  version: Version;
  date: Date;
  onFinish: () => void;
  onBack: () => void;
}

const EFFORT_LEVELS = [
  { level: 1, label: 'Easy', desc: 'Warm-up', color: 'bg-green-500', bg: 'bg-green-500/20', border: 'border-green-500/50', text: 'text-green-400' },
  { level: 2, label: 'Mod', desc: 'RPE 6-7', color: 'bg-yellow-500', bg: 'bg-yellow-500/20', border: 'border-yellow-500/50', text: 'text-yellow-400' },
  { level: 3, label: 'Hard', desc: 'RPE 8-9', color: 'bg-orange-500', bg: 'bg-orange-500/20', border: 'border-orange-500/50', text: 'text-orange-400' },
  { level: 4, label: 'Max', desc: 'Failure', color: 'bg-red-500', bg: 'bg-red-500/20', border: 'border-red-500/50', text: 'text-red-400' },
];

export const WorkoutSession: React.FC<WorkoutSessionProps> = ({ day, version, date, onFinish, onBack }) => {
  const [activeExercises, setActiveExercises] = useState<Exercise[]>([]);
  const [logs, setLogs] = useState<ExerciseLog[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showFeedback, setShowFeedback] = useState(false);
  const [feedback, setFeedback] = useState('');
  const [isRestored, setIsRestored] = useState(false);
  const isInitialLoad = useRef(true);

  const [swapIndex, setSwapIndex] = useState<number | null>(null);
  const [effortPicker, setEffortPicker] = useState<{ exerciseId: string, setIndex: number } | null>(null);

  // Initial Load: Check for drafts and apply previous substitutions
  useEffect(() => {
    const draft = getDraft(day.id);
    const todayStr = date.toISOString().split('T')[0];
    const draftDateStr = draft?.date ? new Date(draft.date).toISOString().split('T')[0] : null;

    if (draft && draftDateStr === todayStr) {
      // Restore from draft
      setActiveExercises(draft.exercises);
      setLogs(draft.logs);
      setIsRestored(true);
      setTimeout(() => setIsRestored(false), 3000);
    } else {
      // Fresh start: Apply previous substitutions if they exist
      const prefs = getExercisePreferences(day.id);
      const dayAlternates = SUBSTITUTION_MATRIX[day.id] || {};

      const preparedExercises = day.exercises.map(ex => {
        if (ex.isRest) return ex;
        const preferredId = prefs[ex.order];
        if (preferredId && preferredId !== ex.id) {
          // Find this exercise in the matrix
          const alts = dayAlternates[ex.order] || [];
          const found = alts.find(a => a.id === preferredId);
          return found || ex;
        }
        return ex;
      });

      setActiveExercises(preparedExercises);

      const initialLogs: ExerciseLog[] = preparedExercises
        .filter(e => !e.isRest)
        .map(e => {
          const lastLog = getLastLogForExercise(e.id);
          const setLogsCount = e.sets || 1;

          return {
            exerciseId: e.id,
            setLogs: Array(setLogsCount).fill(null).map((_, i) => ({
              weight: lastLog?.setLogs[i]?.weight || lastLog?.setLogs[0]?.weight || '',
              reps: lastLog?.setLogs[i]?.reps || lastLog?.setLogs[0]?.reps || '',
              effort: lastLog?.setLogs[i]?.effort || 2,
              completed: false
            }))
          };
        });
      setLogs(initialLogs);
    }
    isInitialLoad.current = false;
  }, [day.id]);

  // Auto-save logic: Trigger whenever logs or exercises change
  useEffect(() => {
    if (isInitialLoad.current || activeExercises.length === 0) return;

    saveDraft({
      dayId: day.id,
      exercises: activeExercises,
      logs: logs,
      date: date.toISOString()
    });
  }, [logs, activeExercises, day.id, date]);

  const updateLog = (exerciseId: string, setIndex: number, field: keyof ExerciseLog['setLogs'][0], value: any) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const newSets = [...log.setLogs];
      newSets[setIndex] = { ...newSets[setIndex], [field]: value };
      return { ...log, setLogs: newSets };
    }));
  };

  const toggleComplete = (exerciseId: string, setIndex: number) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const newSets = [...log.setLogs];
      newSets[setIndex] = { ...newSets[setIndex], completed: !newSets[setIndex].completed };
      return { ...log, setLogs: newSets };
    }));
  };

  const addSet = (exerciseId: string) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const lastSet = log.setLogs[log.setLogs.length - 1];
      const newSet = {
        weight: lastSet?.weight || '',
        reps: lastSet?.reps || '',
        effort: lastSet?.effort || 2,
        completed: false
      };
      return { ...log, setLogs: [...log.setLogs, newSet] };
    }));
  };

  const removeSet = (exerciseId: string) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      if (log.setLogs.length <= 1) return log;
      return { ...log, setLogs: log.setLogs.slice(0, -1) };
    }));
  };

  const getAlternates = (currentEx: Exercise): Exercise[] | null => {
    if (currentEx.isRest) return null;

    const baseDay = WORKOUTS[version][day.id];
    const mainEx = baseDay?.exercises.find(e => e.order === currentEx.order);

    const dayMatrix = SUBSTITUTION_MATRIX[day.id];
    const matrixAlts = dayMatrix && dayMatrix[currentEx.order] ? dayMatrix[currentEx.order] : [];

    const allOptions = [];
    if (mainEx) allOptions.push(mainEx);
    allOptions.push(...matrixAlts);

    const unique = Array.from(new Map(allOptions.map(item => [item.id, item])).values());

    return unique.length > 1 ? unique : null;
  };

  const handleSwapExercise = (newEx: Exercise) => {
    if (swapIndex === null) return;

    const oldEx = activeExercises[swapIndex];
    if (oldEx.id === newEx.id) {
      setSwapIndex(null);
      return;
    }

    // Persist this substitution for next time
    saveExercisePreference(day.id, oldEx.order, newEx.id);

    const updatedExercises = [...activeExercises];
    updatedExercises[swapIndex] = newEx;
    setActiveExercises(updatedExercises);

    setLogs(prev => {
      const existingNewExLog = prev.find(l => l.exerciseId === newEx.id);

      // If we already have logs for this new exercise (maybe we swapped back), keep them
      if (existingNewExLog) return prev;

      // Otherwise, initialize fresh logs for the new exercise
      const lastLog = getLastLogForExercise(newEx.id);
      const setLogsCount = newEx.sets || 1;
      const newExLog = {
        exerciseId: newEx.id,
        setLogs: Array(setLogsCount).fill(null).map((_, i) => ({
          weight: lastLog?.setLogs[i]?.weight || lastLog?.setLogs[0]?.weight || '',
          reps: lastLog?.setLogs[i]?.reps || lastLog?.setLogs[0]?.reps || '',
          effort: lastLog?.setLogs[i]?.effort || 2,
          completed: false
        }))
      };

      return prev.map(log => log.exerciseId === oldEx.id ? newExLog : log);
    });

    setSwapIndex(null);
  };

  const handleFinish = async () => {
    setIsSubmitting(true);
    const sessionLog = {
      id: Date.now().toString(),
      date: date.toISOString(),
      version,
      dayId: day.id,
      exercises: logs
    };
    saveLog(sessionLog);
    const aiFeedback = await analyzeSession(sessionLog);
    setFeedback(aiFeedback);
    setShowFeedback(true);
    setIsSubmitting(false);
  };

  if (showFeedback) {
    return (
      <div className="flex flex-col h-full justify-center items-center p-6 text-center animate-fade-in pt-safe">
        <div className="bg-blue-500/10 p-5 rounded-full mb-6 ring-2 ring-blue-500/20 shadow-lg shadow-blue-500/10">
           <CheckCircle2 className="w-20 h-20 text-blue-500" />
        </div>
        <h2 className="text-3xl font-bold text-white mb-2">Workout Complete!</h2>
        <div className="bg-slate-800 p-6 rounded-3xl border border-slate-700 w-full text-left mb-8 shadow-2xl">
          <div className="flex items-center gap-2 mb-4 text-yellow-400 font-bold uppercase tracking-wider text-sm">
             <Info size={16} />
             <span>Coach's Notes</span>
          </div>
          <p className="text-slate-300 leading-relaxed whitespace-pre-wrap text-base">{feedback}</p>
        </div>
        <button onClick={onFinish} className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold text-lg py-4 rounded-2xl transition shadow-xl shadow-blue-900/40 active:scale-[0.98]">
          Return to Dashboard
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6 relative pb-8">
      {/* Draft Restoration Notification */}
      {isRestored && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-50 animate-bounce">
           <div className="bg-blue-600 text-white px-4 py-2 rounded-full text-xs font-bold shadow-lg flex items-center gap-2 border border-white/20">
              <Sparkles size={14} fill="currentColor" />
              Progress Restored
           </div>
        </div>
      )}

      <div className="flex flex-col gap-1 px-1">
        <div className="flex items-center gap-3">
          <button onClick={() => onBack()} className="p-3 -ml-3 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors active:scale-90">
            <ChevronLeft size={32} />
          </button>
          <h1 className="text-2xl font-bold text-white leading-tight">{day.title}</h1>
        </div>
        <div className="flex items-center gap-2">
           <div className="h-1.5 w-1.5 rounded-full bg-yellow-400"></div>
           <p className="text-yellow-400 font-medium text-sm">{day.focus}</p>
        </div>
      </div>

      <div className="space-y-6">
        {activeExercises.map((exercise, idx) => {
          if (exercise.isRest) {
            return (
              <div key={`rest-${idx}`} className="flex items-center justify-center gap-3 py-6 bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-800 text-slate-400 text-sm font-medium">
                <Clock size={18} />
                <span>Rest: {exercise.notes}</span>
              </div>
            );
          }

          const log = logs.find(l => l.exerciseId === exercise.id);
          const alternates = getAlternates(exercise);

          return (
            <div key={exercise.id} className="bg-slate-800 rounded-3xl overflow-hidden border border-slate-700/50 shadow-lg animate-fade-in">
              {/* Header */}
              <div className="p-4 bg-slate-800 border-b border-slate-700/50">
                 <div className="flex justify-between items-start mb-2">
                    <button 
                        onClick={() => alternates && setSwapIndex(idx)}
                        disabled={!alternates}
                        className={`flex items-center gap-2 px-2.5 py-1 rounded-lg border transition-all ${
                          alternates 
                            ? 'bg-blue-500/10 border-blue-500/30 text-blue-400 active:bg-blue-500/20' 
                            : 'border-transparent bg-slate-700/30 text-slate-400 cursor-default'
                        }`}
                      >
                         <span className="font-bold text-sm">{exercise.order}</span>
                         {alternates && <RefreshCw size={12} />}
                      </button>
                      <div className="px-2.5 py-1 rounded-lg bg-slate-950/50 border border-slate-700 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                         {exercise.weightGuide}
                      </div>
                 </div>
                 <h3 className="font-bold text-white text-xl leading-snug mb-2">{exercise.name}</h3>
                 <div className="flex flex-wrap gap-y-1 gap-x-3 text-xs text-slate-400 font-medium">
                    <span className="flex items-center gap-1"><Clock size={12} /> {exercise.tempo}</span>
                    <span className="text-slate-600">•</span>
                    <span className="flex items-center gap-1"><Gauge size={12} /> {exercise.reps} Reps</span>
                 </div>
              </div>

              <div className="p-3 space-y-3 bg-slate-900/20">
                {/* Headers Row */}
                <div className="grid grid-cols-[24px_1fr_1fr_1fr_50px] gap-3 px-1 text-[10px] text-slate-500 uppercase font-bold tracking-wider text-center">
                  <div>#</div>
                  <div>Lbs</div>
                  <div>Reps</div>
                  <div>RPE</div>
                  <div>OK</div>
                </div>

                {log?.setLogs.map((set, setIdx) => (
                  <div key={setIdx} className={`grid grid-cols-[24px_1fr_1fr_1fr_50px] gap-3 items-center transition-all ${set.completed ? 'opacity-80' : 'opacity-100'}`}>

                    {/* Set Number */}
                    <div className="flex justify-center">
                       <span className={`text-xs font-bold font-mono ${set.completed ? 'text-blue-400' : 'text-slate-500'}`}>{setIdx + 1}</span>
                    </div>

                    {/* Weight Input */}
                    <div className="relative">
                      <input 
                        type="number"
                        pattern="[0-9]*"
                        inputMode="decimal"
                        className={`w-full bg-slate-950 border rounded-xl py-3.5 text-center text-base font-semibold text-white focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all shadow-sm ${set.completed ? 'border-blue-900/50 text-blue-100' : 'border-slate-700'}`}
                        value={set.weight}
                        placeholder="-"
                        onChange={(e) => updateLog(exercise.id, setIdx, 'weight', e.target.value)}
                      />
                    </div>

                    {/* Reps Input */}
                    <div className="relative">
                      <input 
                        type="number"
                        pattern="[0-9]*"
                        inputMode="numeric"
                        className={`w-full bg-slate-950 border rounded-xl py-3.5 text-center text-base font-semibold text-white focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all shadow-sm ${set.completed ? 'border-blue-900/50 text-blue-100' : 'border-slate-700'}`}
                        value={set.reps}
                        placeholder="-"
                        onChange={(e) => updateLog(exercise.id, setIdx, 'reps', e.target.value)}
                      />
                    </div>

                    {/* Effort Button */}
                    <button 
                      onClick={() => setEffortPicker({ exerciseId: exercise.id, setIndex: setIdx })}
                      className={`h-full w-full flex flex-col items-center justify-center rounded-xl border transition-all active:scale-95 ${
                        EFFORT_LEVELS[set.effort - 1].bg
                      } ${EFFORT_LEVELS[set.effort - 1].border}`}
                    >
                      <span className={`text-xs font-bold ${EFFORT_LEVELS[set.effort - 1].text}`}>
                        {EFFORT_LEVELS[set.effort - 1].label}
                      </span>
                    </button>

                    {/* Check Button */}
                    <div className="flex justify-center">
                      <button 
                        onClick={() => toggleComplete(exercise.id, setIdx)}
                        className={`h-12 w-12 flex items-center justify-center rounded-full transition-all active:scale-90 shadow-sm ${set.completed ? 'bg-blue-500 text-white shadow-blue-500/40 ring-2 ring-blue-500/20' : 'bg-slate-800 text-slate-500 border border-slate-700 hover:bg-slate-700'}`}
                      >
                        {set.completed ? <Check size={26} strokeWidth={3} /> : <div className="w-6 h-6 rounded-full border-2 border-slate-600" />}
                      </button>
                    </div>
                  </div>
                ))}
              </div>

              {/* Footer Actions */}
              <div className="p-3 flex gap-3 border-t border-slate-700/30 bg-slate-800">
                  <button onClick={() => addSet(exercise.id)} className="flex-1 flex items-center justify-center gap-2 py-3 rounded-xl bg-slate-700/30 text-blue-400 font-bold text-sm border border-slate-700/50 active:bg-slate-700/50 transition-colors">
                    <Plus size={16} /> Add Set
                  </button>
                  <button onClick={() => removeSet(exercise.id)} className="w-12 flex items-center justify-center rounded-xl bg-slate-700/30 text-slate-500 border border-slate-700/50 active:bg-red-900/20 active:text-red-400 transition-colors">
                    <Trash2 size={18} />
                  </button>
              </div>

              <div className="bg-slate-950/30 px-4 py-3 text-xs text-slate-400 flex gap-3 leading-relaxed border-t border-slate-700/20">
                 <Info size={16} className="shrink-0 mt-0.5 text-blue-500/70" />
                 <span>{exercise.notes}</span>
              </div>
            </div>
          );
        })}
      </div>

      <div className="pt-8 sticky bottom-4 z-20 px-2">
         <button 
           onClick={handleFinish}
           disabled={isSubmitting}
           className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold text-lg py-4 rounded-2xl shadow-xl shadow-blue-900/30 flex items-center justify-center gap-3 transition-all active:scale-[0.98]"
         >
           {isSubmitting ? <span className="animate-pulse">Analyzing...</span> : <><Save size={20} /> Complete Workout</>}
         </button>
      </div>

      {/* --- EFFORT PICKER SHEET --- */}
      {effortPicker && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center bg-slate-950/80 backdrop-blur-sm animate-fade-in" onClick={() => setEffortPicker(null)}>
          <div className="bg-slate-900 w-full max-w-md rounded-t-3xl border-t border-white/10 shadow-2xl p-6 pb-safe space-y-6 animate-slide-up" onClick={e => e.stopPropagation()}>
             <div className="flex justify-between items-center">
               <div>
                 <h3 className="text-white font-bold text-xl flex items-center gap-2">
                   How did that feel?
                 </h3>
                 <p className="text-slate-400 text-sm mt-1">Set {effortPicker.setIndex + 1}</p>
               </div>
               <button onClick={() => setEffortPicker(null)} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors">
                 <X size={24} />
               </button>
             </div>

             <div className="grid grid-cols-2 gap-4">
               {EFFORT_LEVELS.map((level) => {
                 const currentLog = logs.find(l => l.exerciseId === effortPicker.exerciseId);
                 const currentSet = currentLog?.setLogs[effortPicker.setIndex];
                 const isSelected = currentSet?.effort === level.level;

                 return (
                   <button
                     key={level.level}
                     onClick={() => {
                        updateLog(effortPicker.exerciseId, effortPicker.setIndex, 'effort', level.level);
                        setEffortPicker(null);
                     }}
                     className={`w-full text-left p-4 rounded-2xl border-2 transition-all flex flex-col gap-2 relative overflow-hidden ${
                       isSelected 
                       ? `${level.bg} ${level.border} ring-2 ring-white/10` 
                       : 'bg-slate-800 border-slate-700 active:scale-95'
                     }`}
                   >
                     <div className={`text-sm font-bold uppercase tracking-wider ${level.text}`}>
                       Level {level.level}
                     </div>
                     <div className="font-bold text-xl text-white">
                        {level.label}
                     </div>
                     <div className="text-xs text-slate-400">
                        {level.desc}
                     </div>
                     {isSelected && (
                       <div className="absolute top-3 right-3 bg-white rounded-full p-1 shadow-sm">
                         <Check size={14} className="text-slate-900" strokeWidth={3} />
                       </div>
                     )}
                   </button>
                 )
               })}
             </div>
          </div>
        </div>
      )}

      {/* --- SWAP EXERCISE MODAL --- */}
      {swapIndex !== null && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center sm:items-center p-0 sm:p-4 bg-slate-950/80 backdrop-blur-sm animate-fade-in" onClick={() => setSwapIndex(null)}>
          <div className="bg-slate-900 w-full max-w-md rounded-t-3xl sm:rounded-3xl border border-white/10 shadow-2xl overflow-hidden max-h-[85vh] flex flex-col animate-slide-up" onClick={e => e.stopPropagation()}>
             <div className="p-5 border-b border-white/5 flex justify-between items-center bg-slate-800/50">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-500/10 rounded-lg text-blue-400">
                    <RefreshCw size={20} />
                 </div>
                 <div>
                    <h3 className="text-white font-bold text-lg">Swap Exercise</h3>
                    <p className="text-slate-400 text-xs">Select a variation</p>
                 </div>
               </div>
               <button onClick={() => setSwapIndex(null)} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white"><X size={24} /></button>
             </div>
             <div className="overflow-y-auto p-4 space-y-3 bg-slate-950/50 flex-1 pb-safe">
                {getAlternates(activeExercises[swapIndex])?.map((alt) => {
                  const isCurrent = alt.id === activeExercises[swapIndex!].id;
                  return (
                    <button 
                      key={alt.id}
                      onClick={() => handleSwapExercise(alt)}
                      className={`w-full text-left p-5 rounded-2xl border-2 transition-all active:scale-[0.98] ${
                        isCurrent 
                        ? 'bg-blue-600/10 border-blue-500' 
                        : 'bg-slate-800 border-slate-700'
                      }`}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] font-bold text-blue-300 bg-blue-900/40 px-2 py-0.5 rounded-md uppercase tracking-wider border border-blue-900/50">
                           {alt.weightGuide}
                        </span>
                        {isCurrent && <div className="bg-blue-500 rounded-full p-1"><Check size={12} className="text-white" strokeWidth={4} /></div>}
                      </div>
                      <div className="font-bold text-lg text-white mb-1">{alt.name}</div>
                      <div className="text-sm text-slate-400 leading-relaxed">{alt.notes}</div>
                    </button>
                  );
                })}
             </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-up {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
        .animate-slide-up {
          animation: slide-up 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .animate-fade-in {
          animation: fadeIn 0.2s ease-out;
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { WorkoutDay, ExerciseLog, Version, Exercise } from '../types';
import { WORKOUTS, SUBSTITUTION_MATRIX } from '../constants';
import { CheckCircle2, Clock, Info, Save, ChevronLeft, RefreshCw, X, Check, Plus, Gauge, Trash2, Sparkles, Zap, ArrowRight, Trophy } from 'lucide-react';
import { saveLog, getLastLogForExercise, saveDraft, getDraft, saveExercisePreference, getExercisePreferences } from '../services/storageService';
import { analyzeSession } from '../services/geminiService';

interface WorkoutSessionProps {
  day: WorkoutDay;
  version: Version;
  date: Date;
  onFinish: () => void;
  onBack: () => void;
}

const EFFORT_LEVELS = [
  { level: 1, label: 'Easy', desc: 'Warm-up', color: 'bg-green-500', bg: 'bg-green-500/20', border: 'border-green-500/50', text: 'text-green-400' },
  { level: 2, label: 'Mod', desc: 'RPE 6-7', color: 'bg-yellow-500', bg: 'bg-yellow-500/20', border: 'border-yellow-500/50', text: 'text-yellow-400' },
  { level: 3, label: 'Hard', desc: 'RPE 8-9', color: 'bg-orange-500', bg: 'bg-orange-500/20', border: 'border-orange-500/50', text: 'text-orange-400' },
  { level: 4, label: 'Max', desc: 'Failure', color: 'bg-red-500', bg: 'bg-red-500/20', border: 'border-red-500/50', text: 'text-red-400' },
];

export const WorkoutSession: React.FC<WorkoutSessionProps> = ({ day, version, date, onFinish, onBack }) => {
  const [activeExercises, setActiveExercises] = useState<Exercise[]>([]);
  const [logs, setLogs] = useState<ExerciseLog[]>([]);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showFeedback, setShowFeedback] = useState(false);
  const [feedback, setFeedback] = useState('');
  const [isRestored, setIsRestored] = useState(false);
  const isInitialLoad = useRef(true);

  const [swapIndex, setSwapIndex] = useState<number | null>(null);
  const [effortPicker, setEffortPicker] = useState<{ exerciseId: string, setIndex: number } | null>(null);

  // Initial Load: Check for drafts and apply previous substitutions
  useEffect(() => {
    const draft = getDraft(day.id);
    const todayStr = date.toISOString().split('T')[0];
    const draftDateStr = draft?.date ? new Date(draft.date).toISOString().split('T')[0] : null;

    if (draft && draftDateStr === todayStr) {
      setActiveExercises(draft.exercises);
      setLogs(draft.logs);
      setIsRestored(true);
      setTimeout(() => setIsRestored(false), 3000);
    } else {
      const prefs = getExercisePreferences(day.id);
      const dayAlternates = SUBSTITUTION_MATRIX[day.id] || {};

      const preparedExercises = day.exercises.map(ex => {
        if (ex.isRest) return ex;
        const preferredId = prefs[ex.order];
        if (preferredId && preferredId !== ex.id) {
          const alts = dayAlternates[ex.order] || [];
          const found = alts.find(a => a.id === preferredId);
          return found || ex;
        }
        return ex;
      });

      setActiveExercises(preparedExercises);

      const initialLogs: ExerciseLog[] = preparedExercises
        .filter(e => !e.isRest)
        .map(e => {
          const lastLog = getLastLogForExercise(e.id);
          const setLogsCount = e.sets || 1;

          return {
            exerciseId: e.id,
            setLogs: Array(setLogsCount).fill(null).map((_, i) => ({
              weight: lastLog?.setLogs[i]?.weight || lastLog?.setLogs[0]?.weight || '',
              reps: lastLog?.setLogs[i]?.reps || lastLog?.setLogs[0]?.reps || '',
              effort: lastLog?.setLogs[i]?.effort || 2,
              completed: false
            }))
          };
        });
      setLogs(initialLogs);
    }
    isInitialLoad.current = false;
  }, [day.id]);

  // Auto-save logic: Trigger whenever logs or exercises change
  useEffect(() => {
    if (isInitialLoad.current || activeExercises.length === 0) return;
    saveDraft({
      dayId: day.id,
      exercises: activeExercises,
      logs: logs,
      date: date.toISOString()
    });
  }, [logs, activeExercises, day.id, date]);

  const updateLog = (exerciseId: string, setIndex: number, field: keyof ExerciseLog['setLogs'][0], value: any) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const newSets = [...log.setLogs];
      newSets[setIndex] = { ...newSets[setIndex], [field]: value };
      return { ...log, setLogs: newSets };
    }));
  };

  const toggleComplete = (exerciseId: string, setIndex: number) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const newSets = [...log.setLogs];
      newSets[setIndex] = { ...newSets[setIndex], completed: !newSets[setIndex].completed };
      return { ...log, setLogs: newSets };
    }));
  };

  const addSet = (exerciseId: string) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      const lastSet = log.setLogs[log.setLogs.length - 1];
      const newSet = {
        weight: lastSet?.weight || '',
        reps: lastSet?.reps || '',
        effort: lastSet?.effort || 2,
        completed: false
      };
      return { ...log, setLogs: [...log.setLogs, newSet] };
    }));
  };

  const removeSet = (exerciseId: string) => {
    setLogs(prev => prev.map(log => {
      if (log.exerciseId !== exerciseId) return log;
      if (log.setLogs.length <= 1) return log;
      return { ...log, setLogs: log.setLogs.slice(0, -1) };
    }));
  };

  const getAlternates = (currentEx: Exercise): Exercise[] | null => {
    if (currentEx.isRest) return null;
    const baseDay = WORKOUTS[version][day.id];
    const mainEx = baseDay?.exercises.find(e => e.order === currentEx.order);
    const dayMatrix = SUBSTITUTION_MATRIX[day.id];
    const matrixAlts = dayMatrix && dayMatrix[currentEx.order] ? dayMatrix[currentEx.order] : [];
    const allOptions = [];
    if (mainEx) allOptions.push(mainEx);
    allOptions.push(...matrixAlts);
    const unique = Array.from(new Map(allOptions.map(item => [item.id, item])).values());
    return unique.length > 1 ? unique : null;
  };

  const handleSwapExercise = (newEx: Exercise) => {
    if (swapIndex === null) return;
    const oldEx = activeExercises[swapIndex];
    if (oldEx.id === newEx.id) {
      setSwapIndex(null);
      return;
    }
    saveExercisePreference(day.id, oldEx.order, newEx.id);
    const updatedExercises = [...activeExercises];
    updatedExercises[swapIndex] = newEx;
    setActiveExercises(updatedExercises);

    setLogs(prev => {
      const existingNewExLog = prev.find(l => l.exerciseId === newEx.id);
      if (existingNewExLog) return prev;
      const lastLog = getLastLogForExercise(newEx.id);
      const setLogsCount = newEx.sets || 1;
      const newExLog = {
        exerciseId: newEx.id,
        setLogs: Array(setLogsCount).fill(null).map((_, i) => ({
          weight: lastLog?.setLogs[i]?.weight || lastLog?.setLogs[0]?.weight || '',
          reps: lastLog?.setLogs[i]?.reps || lastLog?.setLogs[0]?.reps || '',
          effort: lastLog?.setLogs[i]?.effort || 2,
          completed: false
        }))
      };
      return prev.map(log => log.exerciseId === oldEx.id ? newExLog : log);
    });
    setSwapIndex(null);
  };

  const executeSave = (withAI: boolean) => {
    const sessionLog = {
      id: Date.now().toString(),
      date: date.toISOString(),
      version,
      dayId: day.id,
      exercises: logs
    };

    if (withAI) {
      setIsSubmitting(true);
      analyzeSession(sessionLog).then(aiFeedback => {
